// src/components/TourViewer.tsx
"use client";

import React from "react";
import { MarzipanoViewer } from "react-marzipano";

/**
 * TourViewer renders a 360° tour based on the property’s `tourType`.
 * - "iframe"  – simply embeds the provided URL in an <iframe>.
 * - "self"   – uses react‑marzipano to display tiled panoramic assets.
 *   The `tourUrl` is expected to point to a directory containing the
 *   Marzipano multiresolution tile structure (e.g. the folder generated by
 *   the Marzipano toolchain). The component loads the `tiles` JSON config
 *   from `<tourUrl>/tiles.json`.
 */
export function TourViewer({
  tourType,
  tourUrl,
  title,
  location,
}: {
  tourType?: "none" | "iframe" | "self";
  tourUrl?: string;
  title: string;
  location: string;
}) {
  if (!tourType || tourType === "none" || !tourUrl) {
    return null;
  }

  if (tourType === "iframe") {
    return (
      <iframe
        src={tourUrl}
        title={title}
        allow="xr-spatial-tracking"
        style={{ width: "100%", height: "500px", border: "none" }}
      />
    );
  }

  // Self‑hosted Marzipano viewer
  return (
    <div style={{ width: "100%", height: "500px" }}>
      <MarzipanoViewer
        // The `url` points to the directory containing `tiles.json`
        // and the tile image pyramid. The library will fetch the config
        // automatically.
        url={tourUrl}
        // Optional: start looking at the centre of the panorama.
        view={{ yaw: 0, pitch: 0, fov: Math.PI / 2 }}
      />
    </div>
  );
}
